WITH RECURSIVE path(node, route) AS (
  SELECT 'A', ',A,'
  UNION ALL
  SELECT e.dst, p.route || e.dst || ',' FROM edges e JOIN path p ON e.src = p.node
  WHERE instr(p.route, ',' || e.dst || ',') = 0
)
SELECT node FROM path ORDER BY length(route);

